void Game::Shoot()
{
	if (bulletX + 45 < gfx.ScreenWidth && bulletX - 45 > 0
		&& bulletY + 46 < gfx.ScreenHeight && bulletY - 46 > 0)
	{
		DrawBullet(bulletX, bulletY);
		bulletRec = RecF(bulletX, bulletX + 45, bulletY, bulletY + 46);
	}
	else
	{
		bulletX = x;
		bulletY = y;
	}
}


void Game::BlockMove(int x, int y, int speed, int reclife, RecF& arec)
{
	//if not initialized
	if (arec.bottom == 0 && arec.left == 0 && arec.right == 0 && arec.top == 0)
	{
		arec = RecF(x, x + 32, y, y + 32);
		arec.life = reclife;//初始化方块的生命
		countrecs++;
	}
	//Draw blocks
	//如果arec在屏幕范围内 并且arec没有被射落
	if (arec.right < gfx.ScreenWidth && arec.left > 0
		&& arec.bottom + 100 < gfx.ScreenHeight && arec.top > 0
		&&arec.hasshot==false)
	{
		DrawBlock(arec.left, arec.top);
	}
	else if (gfx.ScreenHeight - arec.bottom < 100&&arec.hasshot==false)
	{//方块离底部还有100的时候停下
		DrawBlock(arec.left, arec.top);
		arec.moveable = false;
	}
	//judge whether overlapping
	for (int i = 0; i < 1000; i++)
	{
		if (arec.index!=recs[i].index)//if not the same block
		{
			if (arec.IsOverlappingOf(recs[i].left+16, recs[i].top-1)//如果压到了下面的方块
				&& recs[i].moveable==false)//并且下面的方块已经不能动了
			{
				arec.moveable = false;//这个（上面）的方块就不能动了
			}
		}
	}
	//judge if get shot
	if (Bingo(arec))
	{
		arec.life--;//被射到一次，方块的耐度-1
		if (arec.life == 0)//如果方块的耐度归为0
		{
			arec.bottom = arec.top = arec.left = arec.right = 1;//移动到左上角
			arec.hasshot = true;//被射落了
			arec.moveable = false;//方块被固定到左上角
		}
	}
	//judge whether moveable
	if (arec.moveable)
	{
		arec.top += speed;//往下落，通过移动方块的边界来控制方块
		arec.bottom += speed;
	}
	else
	{
	}
}

void Game::BlockMoveSummer(int x, int y, int speed, int reclife, RecF& arec)
{
	//if not initialized
	if (arec.bottom == 0 && arec.left == 0 && arec.right == 0 && arec.top == 0)
	{
		arec = RecF(x, x + 32, y, y + 32);
		arec.life = reclife;//初始化方块的生命
		countrecs++;
	}
	//Draw blocks
	//如果arec在屏幕范围内 并且arec没有被射落
	if (arec.right < gfx.ScreenWidth && arec.left > 0
		&& arec.bottom + 100 < gfx.ScreenHeight && arec.top > 0 && arec.hasshot == false)
	{
		DrawBlockGreen(arec.left, arec.top);
	}
	else if (gfx.ScreenHeight - arec.bottom < 100 && arec.hasshot == false)
	{//方块离底部还有100的时候停下
		DrawBlockGreen(arec.left, arec.top);
		arec.moveable = false;
	}
	//judge whether overlapping
	for (int i = 0; i < 1000; i++)
	{
		if (arec.index != recs[i].index)//if not the same block
		{
			if (arec.IsOverlappingOf(recs[i].left + 16, recs[i].top - 1)//如果压到了下面的方块
				&& recs[i].moveable == false)//并且下面的方块已经不能动了
			{
				arec.moveable = false;//这个（上面）的方块就不能动了
			}
		}
	}
	//judge if get shot
	if (Bingo(arec))
	{
		arec.life--;//被射到一次，方块的耐度-1
		if (arec.life == 0)//如果方块的耐度归为0
		{
			arec.bottom = arec.top = arec.left = arec.right = 1;//移动到左上角
			arec.hasshot = true;//被射落了
			arec.moveable = false;//方块被固定到左上角
			scores(10);
		}
	}
	//judge whether moveable
	if (arec.moveable)
	{
		arec.top += speed;//往下落，通过移动方块的边界来控制方块
		arec.bottom += speed;
	}
	else
	{
	}
}

